"""Count paired region gains and remaining failures,including the quieter V151 control."""

from pathlib import Path

from train_directional_bank_trial import read, ref, save

root=Path('/home/dllu/proj/demosaic/.cache/quality-20261103/V156-local-risk-v1')
current=read(root/'scores-v1.json')
old_root=root.parent/'V151-noisy-objective-v1'
prior=read(old_root/'scores-v1.json')
cases={c['id']:c for c in read(root/'quality-design-v1.json')['observations']}
old_cases={c['id']:c for c in read(old_root/'quality-design-v1.json')['observations']}
assert len(cases)==len(old_cases)==822 and cases.keys()==old_cases.keys()
assert all(cases[k]['arrays']==old_cases[k]['arrays'] and cases[k]['parent']==old_cases[k]['parent'] for k in cases)
now={(r['id'],r['method']):r for r in current['rows']}
before={(r['id'],r['method']):r for r in prior['rows']}
groups=[]
for endpoint in ['raw','EMA']:
    method=f'local-risk-{endpoint}-step1000'
    for baseline,source in [('parent',now),(f'mse-control-{endpoint}-step1000',now),(f'noisy-only-{endpoint}-step1000',before)]:
        for prior_name in ['iso6400-prior','iso12800-prior']:
            ids=[k for k,c in cases.items() if c['kind']=='mixed-quiet' and c['noise']['name']==prior_name]
            assert len(ids)==16
            for field in ['quiet_error_RMS_DN16','quiet_spatial_RMS_DN16','full_error_RMS_DN16']:
                pairs=[(k,now[k,method][field],source[k,baseline][field]) for k in ids]
                delta=[a-b for _,a,b in pairs]
                groups.append({
                    'method':method,'baseline':baseline,'prior':prior_name,'field':field,'cases':16,
                    'better':sum(d<0 for d in delta),'equal':sum(d==0 for d in delta),'worse':sum(d>0 for d in delta),
                    'maximum_increase_DN16':max(delta),'maximum_decrease_DN16':min(delta),
                    'worst_candidate_DN16':max(a for _,a,_ in pairs),'worst_baseline_DN16':max(b for _,_,b in pairs),
                    'pairs':[{'id':k,'candidate':a,'baseline':b,'difference':a-b} for k,a,b in pairs]})
summary=[]
for endpoint in ['raw','EMA']:
    method=f'local-risk-{endpoint}-step1000'
    old=f'noisy-only-{endpoint}-step1000'
    for key in [('mesh',True,None,'template_gain'),('mixed-quiet','iso6400-prior',None,'quiet_error_RMS_DN16'),('mixed-quiet','iso12800-prior',None,'quiet_error_RMS_DN16')]:
        kind,condition,cohort,field=key
        a=next(s[field] for s in current['summary'] if (s['kind'],s['condition'],s['cohort'],s['method'])==(kind,condition,cohort,method))
        b=next(s[field] for s in prior['summary'] if (s['kind'],s['condition'],s['cohort'],s['method'])==(kind,condition,cohort,old))
        summary.append({'method':method,'baseline':old,'kind':kind,'condition':condition,'field':field,'candidate':a,'baseline_value':b,'percent_change':100*(a/b-1)})
save(root/'paired-region-comparison-v1.json',{
    'status':'completed-paired-quiet-counts-and-V151-comparison','scores':ref(root/'scores-v1.json'),
    'V151_scores':ref(old_root/'scores-v1.json'),'same822_input_parent_bindings':True,
    'source':dict(ref(Path(__file__)),text=Path(__file__).read_text()),'groups':groups,'summary':summary,
    'new_forwards':0,'new_noise_draws':0,
    'scope':'Related four-CFA placements/reused recipes,not independent scenes or significance claims. Paired quiet per-case wins/worst errors expose remaining failures despite average gains. Comparison versus matched MSE isolates added loss;comparison to V151 also changes input features/base spectral objective and is not isolated causality.'})
for g in groups:
    if g['field']=='quiet_error_RMS_DN16':
        print(g['method'],g['baseline'],g['prior'],'better/worse',g['better'],g['worse'],'max increase',g['maximum_increase_DN16'],'worst',g['worst_candidate_DN16'])
for s in summary:print(s)
